def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    lru_order = []  # list of keys in order of use (most recent at end)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            to_delete = []
            for k in cache:
                write_time = cache[k][1]
                if write_time + ttl <= t:
                    to_delete.append(k)
            for k in to_delete:
                del cache[k]
                if k in lru_order:
                    lru_order.remove(k)

            # If key already exists, update it and move to end of lru_order
            if key in cache:
                cache[key] = (value, t)
                lru_order.remove(key)
                lru_order.append(key)
            else:
                # Key is absent
                if len(cache) >= capacity:
                    # Evict least recently used
                    lru_key = lru_order.pop(0)
                    del cache[lru_key]

                cache[key] = (value, t)
                lru_order.append(key)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            to_delete = []
            for k in cache:
                write_time = cache[k][1]
                if write_time + ttl <= t:
                    to_delete.append(k)
            for k in to_delete:
                del cache[k]
                if k in lru_order:
                    lru_order.remove(k)

            if key in cache:
                value, write_time = cache[key]
                results.append(value)
                # Make key most recently used
                lru_order.remove(key)
                lru_order.append(key)
            else:
                results.append(-1)

    return results

